"""Assemble the public, versioned blind-test corpus from immutable generation outputs."""
import hashlib,json
from pathlib import Path

ROOT=Path(__file__).resolve().parents[1]
RESEARCH=ROOT/'site/research'

def digest(value):
    return hashlib.sha256(json.dumps(value,ensure_ascii=False,sort_keys=True).encode('utf8')).hexdigest()

def main():
    selected=json.loads((RESEARCH/'selected.json').read_text(encoding='utf8'))
    candidates_path=RESEARCH/'corpus_candidates.json'
    if candidates_path.exists(): selected.extend(json.loads(candidates_path.read_text(encoding='utf8')))
    skilled=json.loads((RESEARCH/'skilled.json').read_text(encoding='utf8'))
    baseline=json.loads((RESEARCH/'baseline.json').read_text(encoding='utf8'))
    expected={r['id'] for r in selected}
    assert len(selected)>=30 and len(expected)==len(selected)
    assert {r['id'] for r in skilled}=={r['id'] for r in baseline}==expected
    assert len(skilled)==len(baseline)==len(selected)
    s={r['id']:r['text'] for r in skilled};b={r['id']:r['text'] for r in baseline}
    version='blind-v2-'+digest([selected,skilled,baseline])[:12]
    rounds=[];registry={}
    for row in selected:
        variants=[];registry[row['id']]={}
        for method,text in [('skilled',s[row['id']]),('published',row['human_text']),('baseline',b[row['id']])]:
            assert isinstance(text,str) and len(text)>20
            candidate_id=digest([row['id'],method,text])[:16]
            registry[row['id']][candidate_id]=method
            variants.append({'id':candidate_id,'method':method,'text':text,'credit':row['translator']+' · '+row['published'] if method=='published' else 'GPT-6.1 Terra · reasoning medium · 29.10.2026','note':{'skilled':'Один независимый ответ с literary-translation-craft. Без ручной доработки.','published':'Исторический опубликованный перевод. Цифровая транскрипция в современной орфографии.','baseline':'Один независимый ответ на просьбу перевести. Без подключённого навыка и ручной доработки.'}[method],'sourceUrl':row['human_url'] if method=='published' else 'https://github.com/deprav1/literary-translation-skills/blob/main/site/METHODS.json'})
        rounds.append({'id':row['id'],'author':row['author'],'title':row['title'],'tag':row['tag'],'source':row['source_text'],'sourceUrl':row['source_url'],'candidates':variants})
    data={'version':version,'cohortSize':10,'rounds':rounds}
    (ROOT/'site/data.json').write_text(json.dumps(data,ensure_ascii=False,indent=2),encoding='utf8')
    (ROOT/'backend/catalog.js').write_text('// Generated by scripts/build_blind_catalog.py; versioned candidate allowlist.\nexport const DATASETS = '+json.dumps({version:registry},ensure_ascii=False,indent=2)+';\n',encoding='utf8')
    methods={'dataset':version,'generated_on':'2026-10-29','selection':f'{len(selected)} matched excerpts across varied authors, genres and translators. Curated preference pilot, not a representative literary benchmark.','cohort_size':10,'blinding':'Source identities are hidden by the interface until a choice, not technically secret in a public static repository. Each participant receives a deterministic ten-fragment cohort from the versioned thirty-plus corpus.','model':'gpt-6.1-terra','reasoning_effort':'medium','generations_per_condition':1,'baseline_prompt':'Translate the entries in translation-input.json into Russian. Return an array of {id,text}. Do not read other files or use additional translation tools.','skilled_prompt':'Read translation-input.json and literary-translation-craft/SKILL.md and its references. Produce complete literary Russian translations, preserving voice, viewpoint, rhythm, uncertainty, and repetitions. Do not read baseline or published translations.','operational_note':'Prompts above describe their semantic content; local output paths and operational write instructions are omitted. Agent-host baseline/system behavior is not fully controlled.','skill_version':'e59426cd3c64fbb361c529c82b4c647486350f4a','manual_postediting':False,'best_of_selection':False,'human_condition':'Historical published translations with rights/source notes per excerpt; age, edition and transcription may affect preference.','source_input_sha256':digest(json.loads((RESEARCH/'translation-input.json').read_text(encoding='utf8'))),'baseline_sha256':digest(baseline),'skilled_sha256':digest(skilled),'interpretation':'Preference for these particular outputs only. No claim that a model, skills, or humans generally outperform another condition.'}
    (ROOT/'site/METHODS.json').write_text(json.dumps(methods,ensure_ascii=False,indent=2),encoding='utf8')
    print(json.dumps({'dataset':version,'rounds':len(rounds),'candidates':sum(len(r['candidates']) for r in rounds)},ensure_ascii=False))

if __name__=='__main__':main()
